1  // depends on "tables/utf8_to_utf16_tables.h"
     2
     3
     4  // Convert up to 12 bytes from utf8 to utf32 using a mask indicating the
     5  // end of the code points. Only the least significant 12 bits of the mask
     6  // are accessed.
     7  // It returns how many bytes were consumed (up to 12).
     8  size_t convert_masked_utf8_to_utf32(const char *input,
     9                             uint64_t utf8_end_of_code_point_mask,
    10                             char32_t *&utf32_output) {
    11    // we use an approach where we try to process up to 12 input bytes.
    12    // Why 12 input bytes and not 16? Because we are concerned with the size of
    13    // the lookup tables. Also 12 is nicely divisible by two and three.
    14    //
    15    //
    16    // Optimization note: our main path below is load-latency dependent. Thus it is maybe
    17    // beneficial to have fast paths that depend on branch prediction but have less latency.
    18    // This results in more instructions but, potentially, also higher speeds.
    19    //
    20    // We first try a few fast paths.
    21    const __m128i in = _mm_loadu_si128((__m128i *)input);
    22    const uint16_t input_utf8_end_of_code_point_mask =
    23        utf8_end_of_code_point_mask & 0xfff;
    24    if(((utf8_end_of_code_point_mask & 0xffff) == 0xffff)) {
    25      // We process the data in chunks of 16 bytes.
    26      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output), _mm_cvtepu8_epi32(in));
    27      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output+4), _mm_cvtepu8_epi32(_mm_srli_si128(in,4)));
    28      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output+8), _mm_cvtepu8_epi32(_mm_srli_si128(in,8)));
    29      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output+12), _mm_cvtepu8_epi32(_mm_srli_si128(in,12)));
    30      utf32_output += 16; // We wrote 16 32-bit characters.
    31      return 16; // We consumed 16 bytes.
    32    }
    33    if(((utf8_end_of_code_point_mask & 0xffff) == 0xaaaa)) {
    34      // We want to take 8 2-byte UTF-8 code units and turn them into 8 4-byte UTF-32 code units.
    35      // There is probably a more efficient sequence, but the following might do.
    36      const __m128i sh = _mm_setr_epi8(1, 0, 3, 2, 5, 4, 7, 6, 9, 8, 11, 10, 13, 12, 15, 14);
    37      const __m128i perm = _mm_shuffle_epi8(in, sh);
    38      const __m128i ascii = _mm_and_si128(perm, _mm_set1_epi16(0x7f));
    39      const __m128i highbyte = _mm_and_si128(perm, _mm_set1_epi16(0x1f00));
    40      const __m128i composed = _mm_or_si128(ascii, _mm_srli_epi16(highbyte, 2));
    41      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output), _mm_cvtepu16_epi32(composed));
    42      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output+4), _mm_cvtepu16_epi32(_mm_srli_si128(composed,8)));
    43      utf32_output += 8; // We wrote 32 bytes, 8 code points.
    44      return 16;
    45    }
    46    if(input_utf8_end_of_code_point_mask == 0x924) {
    47      // We want to take 4 3-byte UTF-8 code units and turn them into 4 4-byte UTF-32 code units.
    48      // There is probably a more efficient sequence, but the following might do.
    49      const __m128i sh = _mm_setr_epi8(2, 1, 0, -1, 5, 4, 3, -1, 8, 7, 6, -1, 11, 10, 9, -1);
    50      const __m128i perm = _mm_shuffle_epi8(in, sh);
    51      const __m128i ascii =
    52          _mm_and_si128(perm, _mm_set1_epi32(0x7f)); // 7 or 6 bits
    53      const __m128i middlebyte =
    54          _mm_and_si128(perm, _mm_set1_epi32(0x3f00)); // 5 or 6 bits
    55      const __m128i middlebyte_shifted = _mm_srli_epi32(middlebyte, 2);
    56      const __m128i highbyte =
    57          _mm_and_si128(perm, _mm_set1_epi32(0x0f0000)); // 4 bits
    58      const __m128i highbyte_shifted = _mm_srli_epi32(highbyte, 4);
    59      const __m128i composed =
    60          _mm_or_si128(_mm_or_si128(ascii, middlebyte_shifted), highbyte_shifted);
    61      _mm_storeu_si128((__m128i *)utf32_output, composed);
    62      utf32_output += 4;
    63      return 12;
    64    }
    65    /// We do not have a fast path available, so we fallback.
    66
    67    const uint8_t idx =
    68        tables::utf8_to_utf16::utf8bigindex[input_utf8_end_of_code_point_mask][0];
    69    const uint8_t consumed =
    70        tables::utf8_to_utf16::utf8bigindex[input_utf8_end_of_code_point_mask][1];
    71    if (idx < 64) {
    72      // SIX (6) input code-code units
    73      // this is a relatively easy scenario
    74      // we process SIX (6) input code-code units. The max length in bytes of six code
    75      // code units spanning between 1 and 2 bytes each is 12 bytes. On processors
    76      // where pdep/pext is fast, we might be able to use a small lookup table.
    77      const __m128i sh =
    78          _mm_loadu_si128((const __m128i *)tables::utf8_to_utf16::shufutf8[idx]);
    79      const __m128i perm = _mm_shuffle_epi8(in, sh);
    80      const __m128i ascii = _mm_and_si128(perm, _mm_set1_epi16(0x7f));
    81      const __m128i highbyte = _mm_and_si128(perm, _mm_set1_epi16(0x1f00));
    82      const __m128i composed = _mm_or_si128(ascii, _mm_srli_epi16(highbyte, 2));
    83      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output), _mm_cvtepu16_epi32(composed));
    84      _mm_storeu_si128(reinterpret_cast<__m128i *>(utf32_output+4), _mm_cvtepu16_epi32(_mm_srli_si128(composed,8)));
    85      utf32_output += 6; // We wrote 12 bytes, 6 code points.
    86    } else if (idx < 145) {
    87      // FOUR (4) input code-code units
    88      const __m128i sh =
    89          _mm_loadu_si128((const __m128i *)tables::utf8_to_utf16::shufutf8[idx]);
    90      const __m128i perm = _mm_shuffle_epi8(in, sh);
    91      const __m128i ascii =
    92          _mm_and_si128(perm, _mm_set1_epi32(0x7f)); // 7 or 6 bits
    93      const __m128i middlebyte =
    94          _mm_and_si128(perm, _mm_set1_epi32(0x3f00)); // 5 or 6 bits
    95      const __m128i middlebyte_shifted = _mm_srli_epi32(middlebyte, 2);
    96      const __m128i highbyte =
    97          _mm_and_si128(perm, _mm_set1_epi32(0x0f0000)); // 4 bits
    98      const __m128i highbyte_shifted = _mm_srli_epi32(highbyte, 4);
    99      const __m128i composed =
   100          _mm_or_si128(_mm_or_si128(ascii, middlebyte_shifted), highbyte_shifted);
   101      _mm_storeu_si128((__m128i *)utf32_output, composed);
   102      utf32_output += 4;
   103    } else if (idx < 209) {
   104      // TWO (2) input code-code units
   105      const __m128i sh =
   106          _mm_loadu_si128((const __m128i *)tables::utf8_to_utf16::shufutf8[idx]);
   107      const __m128i perm = _mm_shuffle_epi8(in, sh);
   108      const __m128i ascii = _mm_and_si128(perm, _mm_set1_epi32(0x7f));
   109      const __m128i middlebyte = _mm_and_si128(perm, _mm_set1_epi32(0x3f00));
   110      const __m128i middlebyte_shifted = _mm_srli_epi32(middlebyte, 2);
   111      __m128i middlehighbyte = _mm_and_si128(perm, _mm_set1_epi32(0x3f0000));
   112      // correct for spurious high bit
   113      const __m128i correct =
   114          _mm_srli_epi32(_mm_and_si128(perm, _mm_set1_epi32(0x400000)), 1);
   115      middlehighbyte = _mm_xor_si128(correct, middlehighbyte);
   116      const __m128i middlehighbyte_shifted = _mm_srli_epi32(middlehighbyte, 4);
   117      const __m128i highbyte = _mm_and_si128(perm, _mm_set1_epi32(0x07000000));
   118      const __m128i highbyte_shifted = _mm_srli_epi32(highbyte, 6);
   119      const __m128i composed =
   120          _mm_or_si128(_mm_or_si128(ascii, middlebyte_shifted),
   121                       _mm_or_si128(highbyte_shifted, middlehighbyte_shifted));
   122      _mm_storeu_si128((__m128i *)utf32_output, composed);
   123      utf32_output += 3;
   124    } else {
   125      // here we know that there is an error but we do not handle errors
   126    }
   127    return consumed;
   128  }
